// Pedido da tela Nova campanha do painel, com qualquer mensagem aprovada na Meta. Na dúvida, é teste:
// só vai aos clientes com modo = "publico" (a confirmação, digitar ENVIAR, fica na tela do painel).
const ZONA = 'America/Sao_Paulo';
const b = $('Webhook: painel').first().json.body ?? {};
const ent = $input.first().json;
const linha = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const MAPA = { bronze: 'Bronze', prata: 'Prata', ouro: 'Ouro', diamante: 'Diamante', legado: 'Diamante' };
const TODAS = ['Bronze', 'Prata', 'Ouro', 'Diamante'];
const erros = [];
if (ent.error) erros.push('Não foi possível ler a mensagem no banco. Confira se as tabelas do painel foram criadas no Postgres.');
const m = ent.modelo ?? null;

const teste = linha(b.modo).toLowerCase() !== 'publico';
const pedidoId = linha(b.pedido_id);
const titulo = linha(b.titulo);
let lista = b.categorias;
if (typeof lista === 'string') lista = lista.split(',');
if (!Array.isArray(lista)) lista = [];
const marcadas = new Set(lista.map((c) => MAPA[linha(c).toLowerCase()]).filter(Boolean));
const categorias = TODAS.filter((c) => marcadas.has(c));

if (!/^[A-Za-z0-9-]{8,64}$/.test(pedidoId)) erros.push('Pedido sem identificação. Recarregue a tela e tente de novo.');
if (!titulo || titulo.length > 120) erros.push('O nome da campanha precisa ter de 1 a 120 caracteres.');
if (!categorias.length) erros.push('Escolha ao menos uma categoria.');
if (!ent.error && !m) erros.push('Mensagem não encontrada. Atualize a lista na tela Mensagens.');
if (m && m.status !== 'APPROVED') erros.push('A mensagem "' + (m.titulo || m.nome) + '" não está aprovada pela Meta.');
if (m && m.suportado === false) erros.push(m.observacao || 'Esta mensagem não pode ser usada em campanha.');

// Um valor por {{n}} do corpo, na ordem: o primeiro nome do cliente ou um texto fixo da campanha.
const qtd = m && Array.isArray(m.variaveis) ? m.variaveis.length : 0;
const recebidos = Array.isArray(b.variaveis) ? b.variaveis : [];
const campos = [];
for (let n = 1; n <= qtd; n++) {
  const v = recebidos.find((x) => Number(x?.n) === n) ?? {};
  const origem = linha(v.origem) === 'nome' ? 'nome' : 'fixo';
  const valor = origem === 'nome' ? '' : linha(v.valor);
  if (origem === 'fixo' && !valor) erros.push('Preencha o campo {{' + n + '}} da mensagem.');
  if (valor.length > 300) erros.push('O campo {{' + n + '}} pode ter até 300 caracteres.');
  campos.push({ n, origem, valor });
}

const agora = DateTime.now().setZone(ZONA);
let inicio = agora;
const textoInicio = linha(b.inicio);
if (textoInicio) {
  const d = /^\d{4}-\d{2}-\d{2}$/.test(textoInicio) ? DateTime.fromISO(textoInicio, { zone: ZONA }).startOf('day') : DateTime.fromISO(textoInicio, { zone: ZONA });
  if (!d.isValid) erros.push('Data de início inválida: ' + textoInicio + '.');
  else if (d > agora) inicio = d;
}

return [{ json: {
  ok: erros.length === 0,
  erros: [...new Set(erros)],
  origem: 'painel',
  teste,
  // A chave impede criar a mesma campanha duas vezes (clique duplo, envio repetido); o painel gera um ID por pedido.
  chave: (teste ? 'teste-' : '') + 'painel-' + pedidoId,
  titulo: teste ? 'Teste · ' + titulo : titulo,
  categorias,
  campos,
  nao_repetir: b.nao_repetir !== false,
  inicio: inicio.toUTC().toISO(),
  criada_por: linha(b.criada_por),
  modelo: m ? { id: m.id, nome: m.nome, idioma: m.idioma, titulo: m.titulo, cabecalho: m.cabecalho, corpo: m.corpo, rodape: m.rodape, botoes: m.botoes || [] } : null,
} }];

const linha = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const CATEGORIAS = { bronze: 'Bronze', prata: 'Prata', ouro: 'Ouro', legado: 'Diamante', diamante: 'Diamante' };
function celular(v) {
  let n = String(v ?? '').replace(/\D/g, '').replace(/^0+/, '');
  if (n.length === 10 || n.length === 11) n = '55' + n;
  // Celular brasileiro sem o nono dígito: 55 + DDD + 8 dígitos começando em 6 a 9.
  if (/^55\d{2}[6-9]\d{7}$/.test(n)) n = n.slice(0, 4) + '9' + n.slice(4);
  return /^\d{12,15}$/.test(n) ? n : '';
}

const cfg = $('Ler configuração e mensagem').first().json.cfg;
const pedido = $('Validar pedido').first().json;
const m = pedido.modelo;
const suporte = celular(cfg.whatsapp_suporte);
const ignorados = { inativo: 0, fora_da_categoria: 0, sem_celular: 0, centralizador: 0, sem_aceite: 0, sem_nome: 0, repetido: 0 };
const candidatos = [];
let totalBase44 = 0;

if (pedido.teste) {
  // Teste: só os telefones de config_disparos.telefones_teste, com o nome "Teste".
  for (const t of Array.isArray(cfg.telefones_teste) ? cfg.telefones_teste : []) {
    const telefone = celular(t);
    if (telefone && !candidatos.some((c) => c.telefone === telefone)) {
      candidatos.push({ cliente_id: 'teste:' + telefone, telefone, primeiro_nome: 'Teste', categoria: null });
    }
  }
} else {
  // O Base44 devolve { clientes: [...] }; se vier uma lista solta, o n8n já separou em itens.
  const itens = $input.all().map((i) => i.json);
  const clientes = itens.length === 1 && Array.isArray(itens[0].clientes) ? itens[0].clientes : itens.filter((c) => c && c.cliente_id);
  totalBase44 = clientes.length;
  const ids = new Set();
  const telefones = new Set();
  for (const c of clientes) {
    const id = linha(c.cliente_id);
    if (!id) continue;
    if (c.ativo === false) { ignorados.inativo++; continue; }
    const categoria = CATEGORIAS[linha(c.categoria).toLowerCase()] || '';
    if (!pedido.categorias.includes(categoria)) { ignorados.fora_da_categoria++; continue; }
    const telefone = celular(c.celular);
    if (!telefone) { ignorados.sem_celular++; continue; }
    if (suporte && telefone === suporte) { ignorados.centralizador++; continue; }
    if (cfg.exigir_aceite === true && c.aceita_comunicacao !== true) { ignorados.sem_aceite++; continue; }
    const nome = linha(c.primeiro_nome).split(' ')[0];
    if (!nome) { ignorados.sem_nome++; continue; }
    if (ids.has(id) || telefones.has(telefone)) { ignorados.repetido++; continue; }
    ids.add(id);
    telefones.add(telefone);
    candidatos.push({ cliente_id: id, telefone, primeiro_nome: nome, categoria });
  }
}

// O texto completo fica no disparo para o agente saber o que o cliente recebeu.
const renderizar = (texto, vars) => String(texto || '').replace(/\{\{\s*(\d+)\s*\}\}/g, (_, n) => vars[Number(n) - 1] ?? '');
const textoCompleto = (vars) => [
  m.cabecalho ? '*' + m.cabecalho + '*' : '',
  renderizar(m.corpo, vars),
  m.rodape ? '_' + m.rodape + '_' : '',
  (m.botoes || []).length ? 'Botões: ' + m.botoes.map((x) => (x.tipo === 'link' ? x.texto + ' (' + x.url + ')' : x.texto)).join(' | ') : '',
].filter(Boolean).join('\n\n');

const fila = candidatos.map((c) => {
  const variaveis = pedido.campos.map((v) => (v.origem === 'nome' ? c.primeiro_nome : v.valor));
  return { ...c, variaveis, texto: textoCompleto(variaveis) };
});
const payload = {
  chave: pedido.chave,
  titulo: pedido.titulo,
  teste: pedido.teste,
  modelo_nome: m.nome,
  modelo_idioma: m.idioma,
  nao_repetir: pedido.nao_repetir,
  parametros: { modelo_id: m.id, modelo_titulo: m.titulo || m.nome, campos: pedido.campos, nao_repetir: pedido.nao_repetir },
  publico: { categorias: pedido.categorias, total_base44: totalBase44, ignorados },
  origem: pedido.origem,
  criada_por: pedido.criada_por,
  inicio: pedido.inicio,
  fila,
};
return [{ json: { payload: JSON.stringify(payload), total_base44: totalBase44, na_lista: fila.length, ignorados } }];

// Resposta ao painel: o que foi criado, quem ficou de fora e quando os envios começam.
const ZONA = 'America/Sao_Paulo';
const pedido = $('Validar pedido').first().json;
const quando = (iso) => DateTime.fromISO(new Date(iso).toISOString()).setZone(ZONA).toFormat("dd/MM/yyyy 'às' HH:mm");
const saida = (http_status, titulo, mensagem, extra = {}) => [{ json: { http_status, resposta: { ok: http_status === 200, titulo, mensagem, ...extra } } }];

if (!pedido.ok) return saida(400, 'A campanha não foi criada', pedido.erros.join(' '), { erros: pedido.erros });
const r = $input.first().json;
if (!r.campanha_id) {
  const msg = 'Esta campanha já foi criada (campanha #' + r.campanha_existente_id + '). Nada foi criado de novo.';
  return saida(409, 'Campanha já criada', msg, { erros: [msg], campanha_id: r.campanha_existente_id });
}
const extra = { campanha_id: r.campanha_id, teste: pedido.teste, na_fila: r.na_fila, status: r.status };
const avisos = [];
if (!r.disparos_ativos) avisos.push('Os envios estão desligados: nada sai até o suporte ligar.');
if (pedido.teste) {
  if (!r.na_fila) avisos.push('Não há celulares de teste cadastrados. Peça ao suporte para cadastrar.');
  return saida(200, 'Teste criado', ['Teste criado (campanha #' + r.campanha_id + '): ' + r.na_fila + ' celular(es) de teste. A mensagem sai na próxima rodada de envio, em até 5 minutos.', ...avisos].join(' '), extra);
}
const partes = ['Campanha #' + r.campanha_id + ' criada com ' + r.na_fila + ' cliente(s) na fila (' + pedido.categorias.join(', ') + ').'];
if (r.adiados_por_frequencia) partes.push(r.adiados_por_frequencia + ' recebem depois do intervalo mínimo entre campanhas.');
if (r.ja_receberam) partes.push(r.ja_receberam + ' já tinham recebido esta mensagem e ficaram de fora.');
if (r.sairam) partes.push(r.sairam + ' pediram para não receber e ficaram de fora.');
if (r.primeiro_envio) partes.push('Os envios começam a partir de ' + quando(r.primeiro_envio) + ', no horário de envio, até ' + r.limite_diario + ' por dia somando todas as campanhas.');
if (r.status === 'pausada') avisos.push('ATENÇÃO: a campanha foi criada PAUSADA porque o modo teste está ligado. Peça ao suporte para desligar e depois retome a campanha na tela Envios.');
if (!r.publico) avisos.push('O app não devolveu nenhum cliente dessas categorias.');
return saida(200, r.status === 'pausada' ? 'Campanha criada, mas pausada' : 'Campanha criada', [...partes, ...avisos].join(' '), extra);
